import itertools
objs='KCM'
# physical boxes 0,1,2; labels dict physical-> color, contents sets

def run(order):
 labs=['red','blue','green']; cont=[{'K'},{'C'},{'M'}]
 for op in order:
  def box_obj(o):
   xs=[i for i,s in enumerate(cont) if o in s]
   if len(xs)"'!=1: raise ValueError
   return xs[0]
  def box_lab(l): return labs.index(l)
  if op=='"'F': # K to C
   src=box_obj('K'); dst=box_obj('C'); cont[src].remove('K');cont[dst].add('K')
  elif op=='A':
   i,j=box_lab('red'),box_lab('green');cont[i],cont[j]=cont[j],cont[i]
  elif op=='B':
   src=box_obj('M');dst=box_lab('red');cont[src].remove('M');cont[dst].add('M')
  elif op=='C':
   i,j=box_obj('K'),box_obj('M');labs[i],labs[j]=labs[j],labs[i]
  elif op=='D':
   src=box_obj('C');dst=box_lab('blue');cont[src].remove('C');cont[dst].add('C')
  elif op=='E':
   i,j=box_obj('C'),box_obj('K');cont[i],cont[j]=cont[j],cont[i]
 return tuple(labs[box_obj(o)] for o in objs)
from collections import defaultdict
out=defaultdict(list)
for p in itertools.permutations('FABCDE'):
 out[run(p)].append(''.join(p))
print(len(out))
for k,v in sorted(out.items(), key=lambda z:-len(z[1])):
 print(k,len(v),v[:8])
